def run_length(s):
    if not s:
        return ""

    encoded = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            encoded.append(s[i - 1])
            if count > 1:
                encoded.append(str(count))
            count = 1

    encoded.append(s[-1])
    if count > 1:
        encoded.append(str(count))

    return ''.join(encoded)
```

